using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SharkRuptureAction", menuName = "Data/Battle/Battle Actions/Cellarius/SharkRupture Action")]
public class SharkRuptureAction : BattleAction
{
	[Header("Purify Action")]
	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	[SerializeField]
	private int additionalTimesAmount = 2;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public PurifiedLightningAction PurifiedLightningAction => purifiedLightningAction;

	public int AdditionalTimesAmount => additionalTimesAmount;

	public PurifyAction PurifyAction => purifyAction;

	public int GetPlayerCurrentCorruption()
	{
		return (int)ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<CorruptionStats>().CurrentCorruption + additionalTimesAmount;
	}

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXDelay(target, purifyAmount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			purifiedLightningAction.SingleTargetCastDefault(target, GetPlayerCurrentCorruption(), purifyAmount, source);
		}
	}

	private IEnumerator VFXDelay(GameObject target, int purifyAmount, GameObject source)
	{
		PlaySFX();
		SpawnVFXOnPlayerPosition(3f);
		yield return new WaitForSeconds(vfxDelay);
		purifiedLightningAction.SingleTargetCastDefault(target, GetPlayerCurrentCorruption(), purifyAmount, source, delegate
		{
			SpawnSecondVFX(GetVFXOwnerPosition(target), 3f);
		});
	}
}
